      'malaj.f4': 'Navigim te projekti i mëparshëm dhe i radhës',
      'malaj.f5': 'Brand book në PDF për shkarkim',
      'malaj.f6': 'Faqet Rreth dhe Shërbime',
      'malaj.f7': 'Kontakt me email dhe telefon me një prekje',
      'malaj.f8': 'Kalime të buta mes faqeve',
